.step-card {
  width: 260px;
  padding: 24px 20px;
  background: linear-gradient(135deg, #43c6ac 0%, #191654 100%);
  border-radius: 20px;
  text-align: center;
  color: white;
  cursor: pointer;
  transition: transform 0.2s;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}
.step-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.2);
}
.steps-display {
  margin-bottom: 12px;
}
.steps-value {
  font-size: 48px;
  font-weight: bold;
}
.steps-unit {
  font-size: 20px;
  margin-left: 4px;
  opacity: 0.8;
}
.steps-label {
  font-size: 18px;
  margin-bottom: 8px;
  opacity: 0.9;
}
.hint {
  font-size: 12px;
  opacity: 0.6;
}

